class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}
        self._tickets = {}
        self._next_id = 1
        self._seq = 0
        self._queue = []  # entries: (vip_flag, priority_rank, seq, ticket_id)

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if customer not in self._customers:
            raise ValueError(f"Unknown customer: {customer}")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Unknown priority: {priority}")

        ticket_id = self._next_id
        self._next_id += 1

        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "state": "open",
        }

        self._seq += 1
        return self._push(ticket_id, self._seq)

    def _push(self, ticket_id: int, seq: int) -> int:
        ticket = self._tickets[ticket_id]
        vip = 1 if self._customers[ticket["customer"]] else 0
        rank = self.PRIORITIES.index(ticket["priority"])
        # Sort key: VIP first, then higher priority, then FIFO by seq
        entry = (vip, rank, seq, ticket_id)
        if not self._queue:
            self._queue.append(entry)
        else:
            # append and re-sort (small sizes assumed for helpdesk queue)
            self._queue.append(entry)
            self._queue.sort(key=lambda e: (-e[0], -e[1], e[2]))
        return ticket_id

    def next_ticket(self) -> int | None:
        while self._queue:
            entry = self._queue.pop(0)
            ticket_id = entry[3]
            ticket = self._tickets.get(ticket_id)
            if ticket and ticket["state"] == "open":
                ticket["state"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        ticket = self._tickets.get(ticket_id)
        if ticket is None:
            raise ValueError(f"Unknown ticket: {ticket_id}")
        ticket["state"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets.get(ticket_id)
        if ticket is None:
            raise ValueError(f"Unknown ticket: {ticket_id}")
        if ticket["state"] == "closed":
            raise ValueError(f"Closed ticket cannot be reopened: {ticket_id}")
        if ticket["state"] == "open":
            return
        ticket["state"] = "open"
        self._seq += 1
        self._push(ticket_id, self._seq)
